SLEEP_AFTER_PATH = 2.0
SLEEP_AFTER_GRIPPER = 3.0

def send_joint_path(path, sock, name):
    print(f'\n=== {name} ===')
    for q in path:
        print([round(x, 4) for x in q])
        cmd = f'movej({q}, a={ACC}, v={VEL})\n'
        sock.sendall(cmd.encode())
        time.sleep(SLEEP_BETWEEN_POINTS)
    time.sleep(SLEEP_AFTER_PATH)

def send_gripper(sock, script_file, action):
    print(f'\n=== Pinza: {action} ===')
    with open(script_file, 'rb') as f:
        sock.sendall(f.read())
    time.sleep(SLEEP_AFTER_GRIPPER)

